// UI adapter for the uploaded pipeline. All report and verdict strings are inert text.
const triageState={health:null,reports:[],runs:[],evidence:[],selected:null,tab:'report',backend:'engine',reproduce:true,customText:'',busy:false,error:'',selectedRun:null};
const escapeT=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const triagePanel=document.createElement('section');triagePanel.id='triage-workspace';triagePanel.className='triage-workspace';triagePanel.hidden=true;$('#fleet-panel').before(triagePanel);
const integrationBanner=document.createElement('section');integrationBanner.className='integration-banner';integrationBanner.innerHTML='<div><strong>PatchWarden security pipeline</strong><p id="integration-status">Connecting to the uploaded backend…</p></div><button class="button" id="open-triage">Open report triage →</button>';$('.summary').before(integrationBanner);$('#open-triage').onclick=()=>{location.hash='scan'};
views.scan=['Vulnerability triage','Verify reports against the uploaded PatchWarden pipeline.','scan','Vulnerability Scan'];
const beforeTriageView=changeView;changeView=function(v){beforeTriageView(v);const active=view==='scan';triagePanel.hidden=!active;integrationBanner.hidden=active||view==='settings';if(active){$('#fleet-panel').hidden=true;$('#attention').hidden=true;$('.summary').hidden=true;ops.hidden=true;$('#scan').hidden=true;$('.demo').textContent='LOCAL PIPELINE';renderTriage()}else{$('.summary').hidden=false;ops.hidden=false;$('.demo').textContent='FLEET DEMO'}};
const beforeTriageRender=render;render=function(){beforeTriageRender();if(view==='scan'){$('#attention').hidden=true;$('#fleet-panel').hidden=true}};
async function triageAPI(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{...options,signal:controller.signal,headers:{'Content-Type':'application/json','X-PatchWarden-Client':'dashboard',...(options.headers||{})}});let payload;try{payload=await response.json()}catch{throw new Error('The connected backend is unavailable. Start the integrated server with node preview.cjs.')}if(!response.ok)throw new Error(payload.error||`Request failed (${response.status})`);return payload}finally{clearTimeout(timer)}}
function currentTriageReport(){return triageState.reports.find(r=>r.id===triageState.selected)}
function currentTriageRun(){if(triageState.selectedRun)return triageState.runs.find(r=>r.id===triageState.selectedRun);return triageState.runs.find(r=>triageState.selected==='custom'?r.report_id===null:r.report_id===triageState.selected)}
function verdictClass(v){return v==='CONFIRMED'?'':v==='INSUFFICIENT_EVIDENCE'?'unknown':'safe'}
function statusText(job){return job.record?.verdict?.verdict?.replaceAll('_',' ')||job.status}
function setBackendStatus(){const h=triageState.health;$('#integration-status').textContent=h?`${h.report_count} bundled reports · Local verifier connected · Requests ${h.requests_version}`:'Backend unavailable. Run node preview.cjs from the dashboard folder.';}
function renderTriage(){if(view!=='scan')return;const s=triageState,report=currentTriageReport(),completed=s.runs.filter(j=>j.status==='completed'),confirmed=completed.filter(j=>j.record?.verdict?.verdict==='CONFIRMED');const current=currentTriageRun();
triagePanel.innerHTML=`<div class="triage-toolbar"><div><span class="backend-pill ${s.health?'':'offline'}"><span class="dot"></span>${s.health?'Local pipeline connected':'Backend unavailable'}</span><span class="count">requests ${escapeT(s.health?.requests_version||'—')}</span></div><div><a href="/legacy/present.html" target="_blank" rel="noopener">Original presentation ↗</a><a href="/api/export" download>Export run history</a><button class="button small" id="triage-refresh">Refresh</button></div></div><div class="triage-stats"><article class="triage-stat"><small>Bundled reports</small><strong>${s.reports.length}</strong><span>Real · fabricated · injection</span></article><article class="triage-stat"><small>Completed local runs</small><strong>${completed.length}</strong><span>Persisted across restarts</span></article><article class="triage-stat"><small>Confirmed verdicts</small><strong class="crimson">${confirmed.length}</strong><span>${completed.filter(j=>j.record?.reproduction?.reproduced===true).length} reproduced locally</span></article></div><div class="pipeline-flow ${s.busy?'busy':''}" id="pipeline-flow"><span class="stage">01 Ingest</span><span>→</span><span class="stage">02 Verify</span><span>→</span><span class="stage">03 Reproduce</span><span>→</span><span class="stage">04 Review</span></div>${s.error?`<div class="triage-error" role="alert">${escapeT(s.error)}</div>`:''}<div class="triage-grid"><aside class="triage-list"><div class="triage-list-head"><h2>Report inbox</h2><span class="count">${s.reports.length}</span></div>${s.reports.map((r,i)=>`<button class="triage-report ${s.selected===r.id?'selected':''}" data-report-id="${escapeT(r.id)}"><span>REPORT ${String(i+1).padStart(3,'0')}</span><strong>${escapeT(r.title)}</strong><small>${escapeT(r.references.join(' · ')||'Source verification')}</small></button>`).join('')}<div class="triage-list-footer"><button class="button" id="custom-report">＋ Submit a report</button><p>Report text is treated as data. The offline verifier targets Requests and the bundled CVE scenario.</p></div></aside><div class="triage-main"><div class="triage-main-head"><div><h2>${escapeT(s.selected==='custom'?'Submit a vulnerability report':report?.title||'Choose a report')}</h2><p>${escapeT(s.selected==='custom'?'Paste a report or load a local Markdown/text file.':report?.metadata?.affected_component||'Imported from the uploaded ZIP')}</p></div></div><div class="triage-controls"><label>Backend <select id="triage-backend"><option value="engine" ${s.backend==='engine'?'selected':''}>Offline verifier</option><option value="bob" ${s.backend==='bob'?'selected':''} ${s.selected==='custom'?'disabled':''}>Imported Bob verdict</option></select></label><label><input type="checkbox" id="triage-reproduce" ${s.reproduce?'checked':''}>Local reproduction</label><button class="button run-triage" id="run-triage" ${s.busy||!s.health||!s.selected?'disabled':''}>${s.busy?'Running pipeline…':'Run triage →'}</button></div><div class="triage-body"><div class="triage-tabs">${[['report','Report'],['result','Run result'],['bob','Bob export'],['evidence','R1 evidence']].map(([id,label])=>`<button data-triage-tab="${id}" aria-pressed="${s.tab===id}">${label}</button>`).join('')}</div><div id="triage-content">${triageContent(report,current)}</div></div></div></div><section class="run-history"><h2>Run history <span class="count">${s.runs.length}</span></h2>${s.runs.length?s.runs.slice(0,20).map(j=>`<button class="run-history-row" data-run-id="${j.id}"><div><strong>${escapeT(j.title)}</strong><small>${escapeT(new Date(j.created_at).toLocaleString())} · ${j.backend==='bob'?'Imported Bob verdict':'Offline verifier'}</small></div><span>${escapeT(statusText(j))}</span></button>`).join(''):'<div class="triage-empty">No runs yet. Choose a bundled report and run triage.</div>'}</section>`;
$('#triage-refresh').onclick=loadTriage;$('#custom-report').onclick=()=>{s.selected='custom';s.selectedRun=null;s.tab='report';s.backend='engine';renderTriage()};$('#triage-backend').onchange=e=>s.backend=e.target.value;$('#triage-reproduce').onchange=e=>s.reproduce=e.target.checked;$('#run-triage').onclick=startTriage;
triagePanel.querySelectorAll('[data-report-id]').forEach(b=>b.onclick=()=>{s.selected=b.dataset.reportId;s.selectedRun=null;s.tab='report';s.error='';renderTriage()});triagePanel.querySelectorAll('[data-triage-tab]').forEach(b=>b.onclick=()=>{s.tab=b.dataset.triageTab;renderTriage()});triagePanel.querySelectorAll('[data-run-id]').forEach(b=>b.onclick=()=>{const job=s.runs.find(j=>j.id===b.dataset.runId);s.selected=job.report_id||'custom';s.selectedRun=job.id;s.tab='result';renderTriage();$('.triage-main').scrollIntoView({behavior:'smooth',block:'start'})});bindTriageContent();}
function triageContent(report,job){const s=triageState;if(s.tab==='report'){if(s.selected==='custom')return `<label class="triage-note" for="report-file">Load .md or .txt (up to 64 KB)</label><input id="report-file" type="file" accept=".md,.txt,text/plain,text/markdown"><label class="triage-note" for="report-editor">Report text</label><textarea class="report-editor" id="report-editor" placeholder="Describe the affected component, behavior, and supporting evidence…">${escapeT(s.customText)}</textarea><p class="triage-warning">This deterministic verifier is scoped to Requests / CVE-2023-32681. It is not a general-purpose AI security assessment.</p>`;return `<pre class="report-text">${escapeT(report?.body||'Select a bundled report from the inbox.')}</pre><p class="triage-note">Internal fixture notes are excluded from triage. No instructions in the report are executed.</p>`}
if(s.tab==='bob'){const bob=report?.bob;if(!bob?.available)return '<div class="triage-empty">No imported Bob verdict is available for this report.</div>';return `<p class="triage-warning">Imported session output from the ZIP. Patch and test claims below are historical statements, not changes performed by this dashboard.</p>${renderVerdict(bob.verdict)}<p class="triage-note">Choose “Imported Bob verdict” and run triage to corroborate it with a fresh localhost reproduction.</p>`}
if(s.tab==='evidence')return `<p class="triage-warning">Archived R1 evidence supplied in the ZIP. SHA-256 checks below verify file integrity, not a fresh reproduction on this machine.</p>${s.evidence.map(e=>`<article class="archive-evidence"><h3>${escapeT(e.label==='fixed'?'Fixed baseline · Requests 2.31.0':'Vulnerable baseline · Requests 2.30.0')} <span class="badge ${e.verified?'compliant':'critical'}">${e.verified?'Hashes verified':'Integrity check failed'}</span></h3><p>${escapeT(e.result.status)} · ${escapeT(e.result.generated_at)}</p><p>Credential observed at destination: <strong>${e.result.observation?.proxy_authorization_present?'Yes':'No'}</strong></p>${e.checks.map(c=>`<p>${escapeT(c.file)}<br><code>${escapeT(c.actual)}</code></p>`).join('')}<details><summary>Read archived evidence report</summary><pre>${escapeT(e.report)}</pre></details></article>`).join('')||'<div class="triage-empty">Evidence is not available.</div>'}`;
if(!job)return '<div class="triage-empty">Run this report to see a verdict, evidence, and reproduction outcome.</div>';if(job.status!=='completed')return `<div class="${job.status==='failed'||job.status==='interrupted'?'triage-error':'triage-loading'}" role="status"><strong>${escapeT(job.status.toUpperCase())}</strong><p>${escapeT(job.detail)}</p></div>`;const r=job.record,rep=r.reproduction;return `<p class="triage-note">${r.triage_backend==='bob-session'?'Imported Bob verdict + fresh optional reproduction':'Fresh deterministic verifier run'} · ${escapeT(r.created_at)}</p>${renderVerdict(r.verdict)}<div class="result-block"><h3>Sandbox reproduction</h3><div class="repro-state ${rep.ran&&rep.reproduced?'':'error'}"><strong>${rep.ran?(rep.reproduced?'Reproduced on localhost':'Not reproduced — inspect details'):'Not run'}</strong><p>${escapeT(rep.detail)}</p><p>Harness: ${escapeT(rep.engine)}${rep.run_id?' · '+escapeT(rep.run_id):''}</p></div></div><p class="triage-warning">No production patches are deployed and no pull request is created. The verdict and sandbox observation are separate results.</p><div class="result-actions"><a class="button" href="/api/runs/${job.id}/download" download>Download result JSON</a><button class="button" id="verify-run" data-job="${job.id}">Verify saved record</button><span id="verify-result" role="status"></span></div>`;}
function renderVerdict(v){return `<div class="triage-result-title"><span class="verdict ${verdictClass(v.verdict)}">${escapeT(v.verdict.replaceAll('_',' '))}</span><span>Confidence: ${escapeT(v.confidence)}</span></div><div class="result-block"><h3>Cited evidence</h3>${v.evidence.length?`<ul class="evidence-list">${v.evidence.map(e=>`<li>${escapeT(e)}</li>`).join('')}</ul>`:'<p>No supporting evidence returned.</p>'}</div><div class="result-block"><h3>Backend action / recommendation</h3><p>${escapeT(v.action)}</p></div>`}
function bindTriageContent(){if($('#report-editor'))$('#report-editor').oninput=e=>triageState.customText=e.target.value;if($('#report-file'))$('#report-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>64000){notify('Report must be under 64 KB.');e.target.value='';return}triageState.customText=await f.text();$('#report-editor').value=triageState.customText};if($('#verify-run'))$('#verify-run').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const result=await triageAPI(`/api/runs/${b.dataset.job}/verify`);$('#verify-result').textContent=result.verified?'✓ SHA-256 verified':'Integrity check failed'}catch(err){$('#verify-result').textContent=err.message}finally{b.disabled=false}}}
async function loadTriage(){try{const [health,reports,runs,evidence]=await Promise.all([triageAPI('/api/health'),triageAPI('/api/reports'),triageAPI('/api/runs'),triageAPI('/api/evidence')]);Object.assign(triageState,{health,reports:reports.reports,runs:runs.runs,evidence:evidence.evidence,error:'',busy:!!health.active_job});if(!triageState.selected)triageState.selected=reports.reports[0]?.id;setBackendStatus();renderTriage();if(health.active_job)pollTriage(health.active_job)}catch(err){triageState.health=null;triageState.error=err.message;setBackendStatus();renderTriage()}}
async function startTriage(){const s=triageState;s.error='';s.busy=true;s.selectedRun=null;s.tab='result';renderTriage();try{const input={backend:s.backend,reproduce:s.reproduce};if(s.selected==='custom')input.text=s.customText;else input.report_id=s.selected;const job=await triageAPI('/api/runs',{method:'POST',body:JSON.stringify(input)});s.runs.unshift(job);s.selectedRun=job.id;renderTriage();addActivity('Connected pipeline started: '+job.title);if(typeof exciteCore==='function')exciteCore('scan');pollTriage(job.id)}catch(err){s.busy=false;s.error=err.message;renderTriage()}}
let triagePollTimer;async function pollTriage(id){clearTimeout(triagePollTimer);try{const job=await triageAPI('/api/runs/'+id);const at=triageState.runs.findIndex(j=>j.id===id);if(at<0)triageState.runs.unshift(job);else triageState.runs[at]=job;const terminal=['completed','failed','interrupted'].includes(job.status);if(terminal){triageState.busy=false;renderTriage();notify(job.status==='completed'?'Triage complete. Verdict and evidence are ready.':'Triage run '+job.status+'. Review the details.')}else{if(view==='scan'&&triageState.tab==='result'&&currentTriageRun()?.id===id){$('#triage-content').innerHTML=triageContent(currentTriageReport(),job);bindTriageContent()}triagePollTimer=setTimeout(()=>pollTriage(id),1000)}}catch(err){triageState.busy=false;triageState.error='Connection interrupted. The run may still be active. Refresh to recover it. '+err.message;renderTriage()}}
changeView(location.hash.slice(1)||'scan');loadTriage();
